diff --git a/tests/unit/utils/floating-textarea-position.test.ts b/tests/unit/utils/floating-textarea-position.test.ts
index 8fd8b49..1efbe60 100644
--- a/tests/unit/utils/floating-textarea-position.test.ts
+++ b/tests/unit/utils/floating-textarea-position.test.ts
@@ -5,9 +5,10 @@ import {
   screenToCanvas,
   calculateFloatingPosition,
   getImageBounds,
+  getObjectBounds,
   FLOATING_PRESETS
 } from '@/utils/canvas/floating-element-position';
-import { ImageObject } from '@/components/canvas/types';
+import { ImageObject, ShapeObject } from '@/components/canvas/types';

 /**
  * Unit tests for floating-element-position utilities
@@ -368,4 +369,55 @@ describe('floating-element-position', () => {
       expect(FLOATING_PRESETS.actionsRight.offset.x).toBe(12);
     });
   });
+
+  describe('getObjectBounds for ShapeObject', () => {
+    const createMockShapeObject = (
+      overrides?: Partial<ShapeObject>
+    ): ShapeObject => ({
+      id: 'test-shape',
+      type: 'shape',
+      position: { x: 200, y: 300 }, // center position in Konva
+      width: 100,
+      height: 80,
+      rotation: 0,
+      visible: true,
+      shapeType: 'rectangle',
+      ...overrides
+    });
+
+    it('should convert center-based shape position to top-left bounds', () => {
+      const shape = createMockShapeObject();
+
+      const bounds = getObjectBounds(shape);
+
+      // For a center-based shape:
+      // top-left x = 200 - 100/2 = 150
+      // top-left y = 300 - 80/2  = 260
+      expect(bounds).toEqual({
+        x: 150,
+        y: 260,
+        width: 100,
+        height: 80
+      });
+    });
+
+    it('should respect shape scaleX and scaleY when computing bounds', () => {
+      const shape = createMockShapeObject({
+        scaleX: 2,
+        scaleY: 0.5
+      });
+
+      const bounds = getObjectBounds(shape);
+
+      // Scaled dimensions: width = 100*2 = 200, height = 80*0.5 = 40
+      // top-left x = 200 - 200/2 = 100
+      // top-left y = 300 - 40/2  = 280
+      expect(bounds).toEqual({
+        x: 100,
+        y: 280,
+        width: 200,
+        height: 40
+      });
+    });
+  });
 });
diff --git a/utils/canvas/floating-element-position.ts b/utils/canvas/floating-element-position.ts
index 7143cba..9983464 100644
--- a/utils/canvas/floating-element-position.ts
+++ b/utils/canvas/floating-element-position.ts
@@ -37,7 +37,8 @@ import {
   ImageObject,
   CanvasObject,
   Panel,
-  isPanelObject
+  isPanelObject,
+  isShapeObject
 } from '@/components/canvas/types';

 // ============================================================================
@@ -177,12 +178,25 @@ export function getObjectBounds(object: CanvasObject): ObjectBounds {

   const scaleX = 'scaleX' in object ? object.scaleX ?? 1 : 1;
   const scaleY = 'scaleY' in object ? object.scaleY ?? 1 : 1;
+  const width = object.width * scaleX;
+  const height = object.height * scaleY;
+
+  // Shapes use center-based positioning in Konva, so we need to convert
+  // the center position to top-left bounds for consistent anchoring.
+  if (isShapeObject(object)) {
+    return {
+      x: object.position.x - width / 2,
+      y: object.position.y - height / 2,
+      width,
+      height
+    };
+  }

   return {
     x: object.position.x,
     y: object.position.y,
-    width: object.width * scaleX,
-    height: object.height * scaleY
+    width,
+    height
   };
 }

